; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpm (CP/M 2.2 / 3 (BDOS console)), starts in normal mode
; ============================================================

			org #0100

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)

ntc_start:
			di
			ld sp, ntc_cpmstack		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; main.bas 12: Input "How many numbers (Return = 2000)"; n
			dw kw_printstrvar, str0
			dw kw_inputint, var_n

			; main.bas 13: If n < 10 Or n > MAXN Then n = MAXN
			dw kw_scpltvl, var_n, 10
			dw kw_ftov, tmp0
			dw kw_scpgtvl, var_n, 2000
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if1_1
			dw kw_ltov, 2000, var_n
if1_1:

			; main.bas 14: Do
do2_t:

			; main.bas 15: Print
			dw kw_printnl

			; main.bas 16: Print "T = turbo, N = normal, X = exit"
			dw kw_printstrvar, str1
			dw kw_printnl

			; main.bas 17: Do : k = UCase$(Inkey$) : Frame : Loop Until (k = "T") Or (k = "N") Or (k = "X")
do3_t:
			dw kw_inkeys, stmp0
			dw kw_strucase, var_k, stmp0
			dw kw_frame
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_strcmpeq, var_k, str4
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, do3_t
do3_e:

			; main.bas 18: If k = "X" Then Exit Do
			dw kw_strcmpeq, var_k, str4
			dw kw_goto_iffalse_n, if4_1
			dw do2_e_go
if4_1:

			; main.bas 20: Randomize 7
			dw kw_seedl, 7

			; main.bas 21: For i = 0 To n
			dw kw_ztov, var_i
			dw kw_vtov, var_n, for5_l
			dw kw_forupv_n, var_i, for5_l, for5_e
for5_t:

			; main.bas 22: a(i) = Rnd(1000)
			dw kw_rndl, 1000, tmp1
			dw kw_aset, arr_a, var_i, tmp1

			; main.bas 23: Next
			dw kw_next1v_n, var_i, for5_l, for5_t
for5_e:

			; main.bas 24: Print IIf(k = "T", "Turbo", "Normal"); ": sorting "; n + 1; " numbers..."
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, ch6_0
			dw kw_strcpy, stmp0, str5
			dw ch6_e_go
ch6_0:
			dw kw_strcpy, stmp0, str6
			dw ch6_e_go
ch6_1:
			dw kw_strcpy, stmp0, str7
ch6_e:
			dw kw_printstrvar, stmp0
			dw kw_addl, var_n, 1, tmp0
			dw kw_printstrvar, str8
			dw kw_printint, tmp0
			dw kw_printstrvar, str9
			dw kw_printnl

			; main.bas 25: t0 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t0

			; main.bas 26: If k = "T" Then
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, if7_1

			; main.bas 27: Turbo On
			dw kw_turbo_on

			; main.bas 28: ShellSort
			dw p_shellsort_c

			; main.bas 29: Turbo Off
			dw kw_turbo_off

			; main.bas 30: Else
			dw if7_e_go
if7_1:

			; main.bas 31: ShellSort
			dw p_shellsort_n_c

			; main.bas 32: End If
if7_e:

			; main.bas 33: t1 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t1

			; main.bas 34: Print "Done - stop the stopwatch"
			dw kw_printstrvar, str10
			dw kw_printnl

			; main.bas 35: For i = 0 To 9
			dw kw_ztov, var_i
for8_t:

			; main.bas 36: Print a(i); " ";
			dw kw_aget, arr_a, var_i, tmp0
			dw kw_printint, tmp0
			dw kw_printstrvar, str11

			; main.bas 37: Next
			dw kw_next1l_n, var_i, 9, for8_t
for8_e:

			; main.bas 38: Print
			dw kw_printnl

			; main.bas 39: If (k = "N") And (System.TicksPerSecond > 0) Then
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp0
			dw if9_1_go

			; main.bas 40: Print "took "; t1 - t0; " ticks = "; (t1 - t0) \ System.TicksPerSecond; "."; ((t1 - t0) Mod System.TicksPerSecond) * 10 \ System.TicksPerSecond; " s"

			; main.bas 41: ElseIf k = "T" Then
if9_1:
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, do2_t

			; main.bas 42: Print "(turbo runs with interrupts off, so"
			dw kw_printstrvar, str16
			dw kw_printnl

			; main.bas 43: Print "time it with the stopwatch)"
			dw kw_printstrvar, str17
			dw kw_printnl

			; main.bas 44: End If
if9_2:
if9_e:

			; main.bas 45: Loop
			dw do2_t_go
do2_e:

			; main.bas 46: End
			dw kw_stop

; ============================================================
; sub shellsort (turbo mode)
; ============================================================

p_shellsort:

			; main.bas 49: Dim gap As Integer, i As Integer, j As Integer, t As Integer

			; main.bas 50: gap = n \ 2
			dw kw_divvl, var_n, 2, var_shellsort_gap

			; main.bas 51: Do While gap > 0
do10_t:
			dw kw_scpgtvl, var_shellsort_gap, 0
			dw kw_goto_iffalse, do10_e

			; main.bas 52: For i = gap To n
			dw kw_vtov, var_shellsort_gap, var_shellsort_i
			dw kw_vtov, var_n, for11_l
			dw kw_forupv, var_shellsort_i, for11_l, for11_e
for11_t:

			; main.bas 53: t = a(i)
			dw kw_aget, arr_a, var_shellsort_i, var_shellsort_t

			; main.bas 54: j = i
			dw kw_vtov, var_shellsort_i, var_shellsort_j

			; main.bas 55: Do While j >= gap
do12_t:
			dw kw_scpgevv, var_shellsort_j, var_shellsort_gap
			dw kw_goto_iffalse, do12_e

			; main.bas 56: If a(j - gap) <= t Then Exit Do
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp0
			dw kw_aget, arr_a, tmp0, tmp0
			dw kw_scplevv, tmp0, var_shellsort_t
			dw kw_goto_iffalse, if13_1
			dw do12_e_go
if13_1:

			; main.bas 57: a(j) = a(j - gap)
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp1
			dw kw_aget, arr_a, tmp1, tmp1
			dw kw_aset, arr_a, var_shellsort_j, tmp1

			; main.bas 58: j = j - gap
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, var_shellsort_j

			; main.bas 59: Loop
			dw do12_t_go
do12_e:

			; main.bas 60: a(j) = t
			dw kw_aset, arr_a, var_shellsort_j, var_shellsort_t

			; main.bas 61: Next
			dw kw_next1v, var_shellsort_i, for11_l, for11_t
for11_e:

			; main.bas 62: gap = gap \ 2
			dw kw_divvl, var_shellsort_gap, 2, var_shellsort_gap

			; main.bas 63: Loop
			dw do10_t_go
do10_e:
			dw p_shellsort_r

; ============================================================
; sub shellsort (normal mode)
; ============================================================

p_shellsort_n:

			; main.bas 49: Dim gap As Integer, i As Integer, j As Integer, t As Integer

			; main.bas 50: gap = n \ 2
			dw kw_divvl, var_n, 2, var_shellsort_gap

			; main.bas 51: Do While gap > 0
do14_t:
			dw kw_scpgtvl, var_shellsort_gap, 0
			dw kw_goto_iffalse_n, do14_e

			; main.bas 52: For i = gap To n
			dw kw_vtov, var_shellsort_gap, var_shellsort_i
			dw kw_vtov, var_n, for15_l
			dw kw_forupv_n, var_shellsort_i, for15_l, for15_e
for15_t:

			; main.bas 53: t = a(i)
			dw kw_aget, arr_a, var_shellsort_i, var_shellsort_t

			; main.bas 54: j = i
			dw kw_vtov, var_shellsort_i, var_shellsort_j

			; main.bas 55: Do While j >= gap
do16_t:
			dw kw_scpgevv, var_shellsort_j, var_shellsort_gap
			dw kw_goto_iffalse_n, do16_e

			; main.bas 56: If a(j - gap) <= t Then Exit Do
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp0
			dw kw_aget, arr_a, tmp0, tmp0
			dw kw_scplevv, tmp0, var_shellsort_t
			dw kw_goto_iffalse_n, if17_1
			dw do16_e_go
if17_1:

			; main.bas 57: a(j) = a(j - gap)
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp1
			dw kw_aget, arr_a, tmp1, tmp1
			dw kw_aset, arr_a, var_shellsort_j, tmp1

			; main.bas 58: j = j - gap
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, var_shellsort_j

			; main.bas 59: Loop
			dw do16_t_go
do16_e:

			; main.bas 60: a(j) = t
			dw kw_aset, arr_a, var_shellsort_j, var_shellsort_t

			; main.bas 61: Next
			dw kw_next1v_n, var_shellsort_i, for15_l, for15_t
for15_e:

			; main.bas 62: gap = gap \ 2
			dw kw_divvl, var_shellsort_gap, 2, var_shellsort_gap

			; main.bas 63: Loop
			dw do14_t_go
do14_e:
			dw p_shellsort_n_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_e_go:			ld sp, do2_e
			jp ntc_xn
ch6_e_go:			ld sp, ch6_e
			jp ntc_xn
if7_e_go:			ld sp, if7_e
			jp ntc_xn
if9_1_go:			ld sp, if9_1
			jp ntc_xn
do2_t_go:			ld sp, do2_t
			jp ntc_xn
do12_e_go:			ld sp, do12_e
			ret
do12_t_go:			ld sp, do12_t
			ret
do10_t_go:			ld sp, do10_t
			ret
do16_e_go:			ld sp, do16_e
			jp ntc_xn
do16_t_go:			ld sp, do16_t
			jp ntc_xn
do14_t_go:			ld sp, do14_t
			jp ntc_xn

p_shellsort_c:		; call shellsort (turbo)
			ld hl, 0
			ld (var_shellsort_gap), hl
			ld hl, 0
			ld (var_shellsort_i), hl
			ld hl, 0
			ld (var_shellsort_j), hl
			ld hl, 0
			ld (var_shellsort_t), hl
			ld (p_shellsort_rs), sp
			ld sp, p_shellsort
			ret
p_shellsort_r:		; end of shellsort
			ld sp, (p_shellsort_rs)
			ret
p_shellsort_n_c:		; call shellsort (normal)
			ld hl, 0
			ld (var_shellsort_gap), hl
			ld hl, 0
			ld (var_shellsort_i), hl
			ld hl, 0
			ld (var_shellsort_j), hl
			ld hl, 0
			ld (var_shellsort_t), hl
			ld (p_shellsort_rs), sp
			ld sp, p_shellsort_n
			jp ntc_xn
p_shellsort_n_r:		; end of shellsort
			ld sp, (p_shellsort_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

arr_a:			ds 4002		; 2001 words
var_n:			dw 0
			db 40			; capacity
var_k:			ds 41
var_i:			dw 0
for5_l:			dw 0
var_t0:			dw 0
var_t1:			dw 0
p_shellsort_rs:			dw 0
var_shellsort_gap:			dw 0
var_shellsort_i:			dw 0
var_shellsort_j:			dw 0
var_shellsort_t:			dw 0
for11_l:			dw 0
for15_l:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 40			; capacity
stmp0:			ds 41

; ============================================================
; Strings
; ============================================================

str0:			db "How many numbers (Return = 2000)? ", 0
str1:			db "T = turbo, N = normal, X = exit", 0
str2:			db "T", 0
str3:			db "N", 0
str4:			db "X", 0
str5:			db "Turbo", 0
str6:			db "Normal", 0
str7:			db 0
str8:			db ": sorting ", 0
str9:			db " numbers...", 0
str10:			db "Done - stop the stopwatch", 0
str11:			db " ", 0
str12:			db "took ", 0
str13:			db " ticks = ", 0
str14:			db ".", 0
str15:			db " s", 0
str16:			db "(turbo runs with interrupts off, so", 0
str17:			db "time it with the stopwatch)", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared
; ------------------------------------------------------------
; Scratch space
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)
ntc_gnlo:		db 0			; ntc_getn: low byte
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)
ntc_lead:		db 0			; printint: digit seen
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity
ntc_sptr:		dw 0			; printbuf: text pointer
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done
ntc_ivar:		dw 0			; inputint / inkey: dest var
ntc_aptr:		dw 0			; atoi: text pointer
ntc_hookon:		db 0			; 1 = the Interrupt hook may run (set, and not running now)
ntc_hookset:	db 0			; 1 = an Interrupt hook is set
ntc_hookpend:	db 0			; 1 = an interrupt came, the hook runs at the next safe point
ntc_hook:		dw 0			; the hook Sub's call stub
ntc_hostix:		dw 0			; host platforms: IX kept over a firmware / BDOS call
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)
				db 40			; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_turbo_on ntc_data @shared
;kw_turbo_on  - Turbo On, used in normal mode: SP is already the thread
;  and interrupts are off inside a keyword, so just carry on.
kw_turbo_on:
			xor a
			ld (ntc_nmode), a
			ret

;## kw_turbo_off ntc_xn ntc_data @shared
;kw_turbo_off  - Turbo Off, used in turbo mode: continue in normal mode
kw_turbo_off:
			ld a, 1
			ld (ntc_nmode), a
			jp ntc_xn

;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			pop hl
			ret z
			ld sp, hl
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_goto_ifzero (normal mode copy)
;kw_goto_ifzero, <var>, <label>  - branch if var = 0
kw_goto_ifzero_n:
			pop hl
			ld a, (hl)
			inc hl
			or (hl)
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			ret nc
			ld sp, hl
			ret
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			ret nc
			ld sp, hl
			ret
; ntc_for_le: jump to the label if var <= limit (loop again)
ntc_for_le:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			ret c
			ld sp, hl
			ret
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			ret c
			ld sp, hl
			ret

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again)
ntc_for_le_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_forupv ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_gt

;## kw_forupv (normal mode copy) ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_gt_n

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			jp ntc_for_le_n

;## kw_next1v ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1v_nc
			inc (hl)
ntc_n1v_nc:
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_le

;## kw_next1v (normal mode copy) ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1v_nc_n
			inc (hl)
ntc_n1v_nc_n:
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_le_n

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			pop hl
			jr z, ntc_ftov_t
			ld (hl), 0
			inc hl
			ld (hl), 0
			ret
ntc_ftov_t:
			ld (hl), #ff
			inc hl
			ld (hl), #ff
			ret

; ============================================================
; Arithmetic
; ============================================================

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_subvv
;kw_subvv, <var1>, <var2>, <destvar>  - var1 - var2
kw_subvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ex de, hl
			or a
			sbc hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_div ntc_data
; HL / DE signed, truncating. (ntc_mode) 0 = quotient, 1 = remainder.
; Remainder takes the dividend's sign. Divide by zero gives
; quotient 0, remainder = dividend. Pops destvar and stores.
ntc_div:
			ld a, d
			or e
			jr nz, ntc_div_nz
			ld a, (ntc_mode)
			or a
			jr nz, ntc_div_store
			ld hl, 0
			jr ntc_div_store
ntc_div_nz:
			ld a, h
			ld (ntc_sgnr), a
			xor d
			ld (ntc_sgnq), a
			bit 7, h
			jr z, ntc_div_hpos
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_hpos:
			bit 7, d
			jr z, ntc_div_dpos
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_div_dpos:
			ld a, h
			ld c, l
			ld hl, 0
			ld b, 16
ntc_div_loop:
			sla c
			rla
			adc hl, hl
			sbc hl, de
			jr nc, ntc_div_one
			add hl, de
			djnz ntc_div_loop
			jr ntc_div_done
ntc_div_one:
			inc c
			djnz ntc_div_loop
ntc_div_done:
			ld b, a
			ld a, (ntc_mode)
			or a
			jr z, ntc_div_q
			ld a, (ntc_sgnr)
			jr ntc_div_sign
ntc_div_q:
			ld h, b
			ld l, c
			ld a, (ntc_sgnq)
ntc_div_sign:
			rla
			jr nc, ntc_div_store
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_store:
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_divvl ntc_div
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			xor a
			ld (ntc_mode), a
ntc_divvl:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			pop de
			jp ntc_div

;## kw_orvv
;kw_orvv, <var1>, <var2>, <destvar>
kw_orvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			or e
			ld e, a
			inc hl
			ld a, (hl)
			or d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scpltvl ntc_cmp
;kw_scpltvl, <var>, <literal>
kw_scpltvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_slt

;## kw_scplevv ntc_cmp
kw_scplevv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_sle

;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sgt

;## kw_scpgevv ntc_cmp
kw_scpgevv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_sge

;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## ntc_rnd_seed
ntc_rnd_seed:	dw 1

;## kw_rndl ntc_rnd_seed ntc_div
;kw_rndl, <literal>, <destvar>
kw_rndl:
			pop de
ntc_rnd:
			ld hl, (ntc_rnd_seed)
			ld a, h
			rra
			ld a, l
			rra
			xor h
			ld h, a
			ld a, l
			rra
			ld a, h
			rra
			xor l
			ld l, a
			xor h
			ld h, a
			ld (ntc_rnd_seed), hl
			bit 7, d
			jr nz, ntc_rnd_zero
			ld a, d
			or e
			jr z, ntc_rnd_zero
			ld a, 1
			ld (ntc_mode), a
			res 7, h
			jp ntc_div
ntc_rnd_zero:
			ld hl, 0
			jp ntc_div_store

;## kw_seedl ntc_rnd_seed
;kw_seedl, <literal>
kw_seedl:
			pop hl
ntc_seed:
			ld a, h
			or l
			jr nz, ntc_seed_ok
			inc l
ntc_seed_ok:
			ld (ntc_rnd_seed), hl
			ret

; ============================================================
; Strings: 0 terminated. A string variable or temp has its capacity
; (1 .. 255 chars) in the byte before it: [cap][text...][0]. Array
; elements have no capacity byte (the caller gives the element size).
; Functions that build a string write into a temp, so they cut at
; NTC_STRMAX (the longest string in the program, set by the compiler);
; kw_strcpy / kw_strcat / input cut at the destination's capacity.
; ============================================================

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_gets ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and DEL (or backspace). HL = buffer (its capacity in the byte
; before it), DE = where to
; jp when done (after the newline). 40 chars max, 0 terminated.
ntc_gets:
			ld (ntc_iptr), hl
			ld (ntc_ilink), de
			dec hl
			ld a, (hl)			; the buffer's capacity
			ld (ntc_icap), a
			xor a
			ld (ntc_icnt), a
ntc_gs_wait:
			ld ix, ntc_gs_key
			jp ntc_plat_getkey
ntc_gs_key:
			cp 13
			jr z, ntc_gs_done
			cp 127
			jr z, ntc_gs_del
			cp 8
			jr z, ntc_gs_del
			cp 32
			jr c, ntc_gs_wait
			ld c, a
			ld a, (ntc_icap)
			ld b, a
			ld a, (ntc_icnt)
			cp b
			jr nc, ntc_gs_wait
			inc a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			ld (hl), c
			inc hl
			ld (ntc_iptr), hl
			ld a, c
			ld ix, ntc_gs_wait
			jp ntc_plat_putc
ntc_gs_del:
			ld a, (ntc_icnt)
			or a
			jr z, ntc_gs_wait
			dec a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			dec hl
			ld (ntc_iptr), hl
			ld ix, ntc_gs_wait
			jp ntc_plat_backspace
ntc_gs_done:
			ld hl, (ntc_iptr)
			ld (hl), 0
			ld ix, (ntc_ilink)
			jp ntc_plat_newline

;## kw_inputint ntc_gets ntc_atoi
;kw_inputint, <var>  - signed decimal, stops at the first non digit
kw_inputint:
			pop hl
			ld (ntc_ivar), hl
			ld hl, ntc_inbuf
			ld de, ntc_atoi
			jp ntc_gets

;## ntc_atoi ntc_data
; text to number into the var at (ntc_ivar). ntc_atoi reads ntc_inbuf,
; ntc_atoi_hl reads HL. Spaces first, then - , then digits (or &H hex).
ntc_atoi:
			ld hl, ntc_inbuf
ntc_atoi_hl:
			ld a, (hl)
			cp ' '
			jr nz, ntc_atoi_sign
			inc hl
			jr ntc_atoi_hl
ntc_atoi_sign:
			ld c, 0
			cp '-'
			jr nz, ntc_atoi_amp
			inc c
			inc hl
			ld a, (hl)
ntc_atoi_amp:
			ld de, 0
			cp '&'
			jr nz, ntc_atoi_loop
			inc hl
			ld a, (hl)
			or #20
			cp 'h'
			jr nz, ntc_atoi_done
			inc hl
ntc_atoi_hex:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr c, ntc_atoi_hd
			or #20
			sub 'a' - '0'
			jr c, ntc_atoi_done
			cp 6
			jr nc, ntc_atoi_done
			add a, 10
ntc_atoi_hd:
			ex de, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			or l
			ld l, a
			ex de, hl
			inc hl
			jr ntc_atoi_hex
ntc_atoi_loop:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr nc, ntc_atoi_done
			ld (ntc_aptr), hl
			ex de, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de
			add hl, hl
			ld e, a
			ld d, 0
			add hl, de
			ex de, hl
			ld hl, (ntc_aptr)
			inc hl
			jr ntc_atoi_loop
ntc_atoi_done:
			ld a, c
			or a
			jr z, ntc_atoi_store
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_atoi_store:
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_inkeys ntc_data ntc_plat_key
;kw_inkeys, <dest>  - Inkey$: the new key press as a string, "" if none
kw_inkeys:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inks_got
			jp ntc_plat_scankey
ntc_inks_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			or a
			ret z
			inc hl
			ld (hl), 0
			ret

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - tick count from the platform (CPC: interrupts, 300 a second,
;  only moving in normal mode)
kw_ticks:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_tk_got
			jp ntc_plat_ticks
ntc_tk_got:
			ex de, hl
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

; ============================================================
; String functions. Numbers are passed as the address of a word
; (a literal goes in as lit_n, a dw in the data). Results go to a
; string buffer (41 bytes). Dest may be the same as the source.
; ============================================================

;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			pop de
			pop hl
ntc_uc_loop:
			ld a, (hl)
			cp 'a'
			jr c, ntc_uc_put
			cp 'z' + 1
			jr nc, ntc_uc_put
			sub 32
ntc_uc_put:
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			jr ntc_uc_loop

;## ntc_plat_data
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; not used (a stream has no rows)
ntc_scols:		db 80			; columns
ntc_bdosa:		db 0			; ntc_bdos: A on return
				ds 256			; the program's real stack
ntc_cpmstack:

;## ntc_plat_bdos ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_bdos - C = BDOS function, DE = argument. A (also in ntc_bdosa)
; and HL come back. IX is kept. Interrupts are on during the call.
; ------------------------------------------------------------
ntc_bdos:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			call 5
			di
			ld sp, (ntc_ip)
			ld (ntc_bdosa), a
			ld ix, (ntc_hostix)
			jp (ix)

;## ntc_plat_screen ntc_plat_bdos ntc_plat_data ntc_data
; ntc_plat_putc - A = character: BDOS 6, count the column
ntc_plat_putc:
			ld e, a
			ld c, 6
			ld (ntc_pclink), ix
			ld ix, ntc_pc_back
			jp ntc_bdos
ntc_pc_back:
			ld ix, (ntc_pclink)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; the terminal wrapped
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - CR LF
ntc_plat_newline:
			ld (ntc_pclink), ix
			ld e, 13
			ld c, 6
			ld ix, ntc_nl_lf
			jp ntc_bdos
ntc_nl_lf:
			ld e, 10
			ld c, 6
			ld ix, ntc_nl_done
			jp ntc_bdos
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld ix, (ntc_pclink)
			jp (ix)

; ntc_plat_backspace - BS, space, BS (only on the current line)
ntc_plat_backspace:
			ld a, (ntc_curx)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_curx), a
			ld (ntc_pclink), ix
			ld e, 8
			ld c, 6
			ld ix, ntc_bs_sp
			jp ntc_bdos
ntc_bs_sp:
			ld e, ' '
			ld c, 6
			ld ix, ntc_bs_back
			jp ntc_bdos
ntc_bs_back:
			ld e, 8
			ld c, 6
			ld ix, (ntc_pclink)
			jp ntc_bdos
ntc_bs_none:
			jp (ix)

	IF NTC_TERM = 0
; ntc_plat_cls - a stream can't be cleared: a new line (unless at the start)
ntc_plat_cls:
			ld a, (ntc_curx)
			or a
			jr nz, ntc_plat_newline
			jp (ix)

; ntc_plat_locate - nothing on a stream
ntc_plat_locate:
			jp (ix)
	ELSE
; ntc_plat_cls - clear and home with the terminal's codes
ntc_plat_cls:
			xor a
			ld (ntc_curx), a
			ld hl, ntc_term_cls
			jp ntc_cpm_puts

; ntc_plat_locate - H = column, L = row, 1 based (kept on an 80 x 24 screen)
ntc_plat_locate:
			ld a, h
			or a
			jr nz, ntc_lc_x
			inc a
ntc_lc_x:
			cp 81
			jr c, ntc_lc_xok
			ld a, 80
ntc_lc_xok:
			ld h, a
			dec a
			ld (ntc_curx), a
			ld a, l
			or a
			jr nz, ntc_lc_y
			inc a
ntc_lc_y:
			cp 25
			jr c, ntc_lc_yok
			ld a, 24
ntc_lc_yok:
			ld l, a
			ld de, ntc_term_buf
		IF NTC_TERM = 1
			; VT52: ESC Y row+31 column+31
			ld a, 27
			ld (de), a
			inc de
			ld a, 'Y'
			ld (de), a
			inc de
			ld a, l
			add a, 31
			ld (de), a
			inc de
			ld a, h
			add a, 31
			ld (de), a
			inc de
		ELSE
			; ANSI: ESC [ row ; column H
			ld a, 27
			ld (de), a
			inc de
			ld a, '['
			ld (de), a
			inc de
			ld a, l
			ld b, '0' - 1
ntc_lc_r10:
			inc b
			sub 10
			jr nc, ntc_lc_r10
			add a, 10 + '0'
			ld c, a
			ld a, b
			cp '0'
			jr z, ntc_lc_r1
			ld (de), a
			inc de
ntc_lc_r1:
			ld a, c
			ld (de), a
			inc de
			ld a, ';'
			ld (de), a
			inc de
			ld a, h
			ld b, '0' - 1
ntc_lc_c10:
			inc b
			sub 10
			jr nc, ntc_lc_c10
			add a, 10 + '0'
			ld c, a
			ld a, b
			cp '0'
			jr z, ntc_lc_c1
			ld (de), a
			inc de
ntc_lc_c1:
			ld a, c
			ld (de), a
			inc de
			ld a, 'H'
			ld (de), a
			inc de
		ENDIF
			xor a
			ld (de), a
			ld hl, ntc_term_buf
			jp ntc_cpm_puts

; ntc_cpm_puts - HL = 0 terminated codes, each through BDOS 6
ntc_cpm_puts:
			ld (ntc_cplink), ix
ntc_cps_loop:
			ld a, (hl)
			or a
			jr z, ntc_cps_done
			inc hl
			ld (ntc_cpsp), hl
			ld e, a
			ld c, 6
			ld ix, ntc_cps_next
			jp ntc_bdos
ntc_cps_next:
			ld hl, (ntc_cpsp)
			jr ntc_cps_loop
ntc_cps_done:
			ld ix, (ntc_cplink)
			jp (ix)
ntc_cplink:		dw 0
ntc_cpsp:		dw 0
ntc_term_buf:	ds 10
		IF NTC_TERM = 1
ntc_term_cls:	db 27, "E", 27, "H", 0		; VT52: clear, home
		ELSE
ntc_term_cls:	db 27, "[2J", 27, "[H", 0	; ANSI: clear, home
		ENDIF
	ENDIF

; ntc_plat_mode - nothing on a terminal
ntc_plat_mode:
			jp (ix)
ntc_pclink:		dw 0

;## ntc_plat_key ntc_plat_bdos ntc_data
; ntc_plat_scankey - A = key or 0 (BDOS 6, E = #FF)
ntc_plat_scankey:
			ld e, #FF
			ld c, 6
			jp ntc_bdos

; ntc_plat_getkey - wait for a key (BDOS 6 until there is one)
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_poll:
			ld e, #FF
			ld c, 6
			ld ix, ntc_gk_back
			jp ntc_bdos
ntc_gk_back:
			or a
			jr z, ntc_gk_poll
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0

;## ntc_plat_frame
ntc_plat_frame:
			jp (ix)

;## ntc_plat_ticks
; ntc_plat_ticks - CP/M has no clock it shares: 0
ntc_plat_ticks:
			ld hl, 0
			jp (ix)

;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - warm boot back to CP/M
ntc_plat_exit:
			jp 0

; ============================================================
; File system (FileSystem class) - BDOS files, FCBs, 128 byte records
; ============================================================
; The class's methods are keywords: they take their arguments
; into fs_a1 .. fs_a3, the result's address into fs_res, and
; jump to fs_go with HL = the routine. fs_go runs the routine on
; the real stack (call / push are fine there, as for BDOS), with
; interrupts on, and stores its HL result at fs_res (fs_go4: a
; Long, high word in fs_hi; fs_go0: no store - the routine writes
; the result itself). A routine that fails jumps to fs_err with
; HL = the status (negative); fs_err unwinds to fs_go.
;
; Slots: 0 is for Load / Save / Delete / Exists / Rename / Size,
; 1 and 2 are the handles Open gives. A slot is FS_SLOT bytes:
;   +0  FCB (36)    +36 mode (0 free, 1 read, 2 write, 3 update)
;   +37 position in the buffer (0-128)
;   +38 buffer state (0 not loaded, 1 loaded, 2 changed)
;   +39 record number in the buffer (2)   +42 buffer (128)
; Every record goes through random read / write (BDOS 33 / 34),
; so reading, writing and Seek all work the same way.

FS_SLOT		equ 170
FS_MODE		equ 36
FS_BPOS		equ 37
FS_BST		equ 38
FS_RECL		equ 39
FS_RECH		equ 40
FS_BUF		equ 42
FS_MAXH		equ 2

FS_NOTFOUND	equ -2
FS_FULL		equ -3
FS_BADNAME	equ -4
FS_NOHANDLE	equ -5
FS_BADHANDLE	equ -6
FS_EOF		equ -7
FS_TOOBIG	equ -8
FS_FAILED	equ -9
FS_EXISTS	equ -10
FS_BADMODE	equ -11


ntc_end:				; the end of the program
